-- The score history of the games in `/games`.
--
-- One row per finished match. The id is generated by the browser and is the
-- claim: a retried finish finds the row it already wrote, instead of creating a
-- second match and paying the same correctness twice. `kind` separates the
-- synonym challenge from the antonym challenge, so the panel on the right shows
-- the game being played rather than a mixed list.
--
-- An abandoned match leaves no row. There is nothing to resume and nothing to
-- score; the questions are built fresh next time.
CREATE TABLE game_matches (
  id TEXT PRIMARY KEY NOT NULL,
  user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  kind TEXT NOT NULL,
  score INTEGER NOT NULL DEFAULT 0,
  questions INTEGER NOT NULL DEFAULT 0,
  seconds INTEGER NOT NULL DEFAULT 0,
  created_at INTEGER NOT NULL
);

CREATE INDEX game_matches_recent ON game_matches(user_id, kind, created_at);
